    async def async_get_segments(self) -> list[Segment]:
        """Return all room segments across every loaded floor map.

        Each segment id encodes the map it belongs to as ``{map_flag}:{segment_id}``
        so that segments can be cleaned on the correct map even when the device
        has multiple floor maps.
        """
        home_map_info = self.coordinator.properties_api.home.home_map_info
        if not home_map_info:
