        return [
            Segment(
                id=f"{vacuum_map.map_flag}:{room.segment_id}",
                name=room.name,
                group=vacuum_map.name,
            )
            for vacuum_map in home_map_info.values()
            for room in vacuum_map.rooms
        ]

    async def async_clean_segments(
        self, segment_ids: list[str], **kwargs: Any
    ) -> None:
        """Clean the given room segments.

        Each segment id is expected in ``{map_flag}:{segment_id}`` format. All
        segments must belong to the same map. If that map is not the currently
        active one, the device is switched to it before cleaning.
        """
        segments_by_map: dict[int, list[int]] = {}
        for segment_id in segment_ids:
            try:
                map_flag_str, segment_str = segment_id.split(":")
