        if not segments_by_map:
            return

        if len(segments_by_map) > 1:
            raise ServiceValidationError(
                translation_domain=DOMAIN,
                translation_key="multiple_maps_in_clean",
                translation_placeholders={
                    "map_flags": ", ".join(
                        str(map_flag) for map_flag in sorted(segments_by_map)
                    ),
                },
            )

        target_map_flag, segments = next(iter(segments_by_map.items()))

        maps_trait = self.coordinator.properties_api.maps
        if target_map_flag != maps_trait.current_map:
            try:
                await maps_trait.set_current_map(target_map_flag)
            except RoborockException as err:
                raise ServiceValidationError(
                    translation_domain=DOMAIN,
                    translation_key="command_failed",
                    translation_placeholders={"command": "load_multi_map"},
                ) from err

        await self.send(RoborockCommand.APP_SEGMENT_CLEAN, [{"segments": segments}])


